import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color,
    DirectionalLight,
    AmbientLight,
    Box3,
    Vector3
  } = THREE;

  const root = new Group();
  const stage = new Group();
  const card = new Group();
  const loadedMesh = new Group();
  const owned = [];
  const timelines = [];
  const primitiveResults = [];
  let hoverTween = null;
  let disposed = false;

  root.add(stage);
  stage.add(card);
  card.add(loadedMesh);

  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );
  const backdrop = new Mesh(
    new PlaneGeometry(7.0, 6.0),
    gradientMaterial
  );
  backdrop.position.set(0, -0.15, -2.5);
  stage.add(backdrop);
  owned.push(backdrop);

  const panelMaterial = new MeshStandardNodeMaterial();
  panelMaterial.color.set('#16161d');
  panelMaterial.roughness = 0.72;
  panelMaterial.metalness = 0.42;

  const panel = new Mesh(
    new BoxGeometry(2.9, 2.24, 0.16),
    panelMaterial
  );
  panel.position.set(0, 0.05, -0.62);
  card.add(panel);
  owned.push(panel);

  const stripMaterial = new MeshStandardNodeMaterial();
  stripMaterial.color.set('#0b0b10');
  stripMaterial.roughness = 0.78;
  stripMaterial.metalness = 0.28;

  const captionStrip = new Mesh(
    new BoxGeometry(2.9, 0.42, 0.13),
    stripMaterial
  );
  captionStrip.position.set(0, -0.86, -0.48);
  card.add(captionStrip);
  owned.push(captionStrip);

  const paperMaterial = new MeshStandardNodeMaterial();
  paperMaterial.color.set('#e8ecf2');
  paperMaterial.roughness = 0.58;
  paperMaterial.metalness = 0.3;

  const paperEdge = new Mesh(
    new BoxGeometry(2.72, 0.025, 0.025),
    paperMaterial
  );
  paperEdge.position.set(0, -0.665, -0.37);
  card.add(paperEdge);
  owned.push(paperEdge);

  const accentMaterial = new MeshStandardNodeMaterial();
  accentMaterial.color.set('#ff2a38');
  accentMaterial.emissive.set('#ff2a38');
  accentMaterial.emissiveIntensity = 1.15;
  accentMaterial.roughness = 0.52;
  accentMaterial.metalness = 0.38;

  const accentBar = new Mesh(
    new BoxGeometry(0.62, 0.035, 0.035),
    accentMaterial
  );
  accentBar.position.set(-0.98, -0.86, -0.38);
  card.add(accentBar);
  owned.push(accentBar);

  const contactMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    new CircleGeometry(1.55, 48),
    contactMaterial
  );
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.0, 0.38, 1.0);
  contactShadow.position.set(0, -1.14, -0.18);
  stage.add(contactShadow);
  owned.push(contactShadow);

  const keyLight = new DirectionalLight('#e8ecf2', 1.05);
  keyLight.position.set(3.2, 3.8, 4.5);
  stage.add(keyLight);
  owned.push(keyLight);

  const rimLight = new DirectionalLight('#ff2a38', 0.72);
  rimLight.position.set(-3.4, 1.6, -1.5);
  stage.add(rimLight);
  owned.push(rimLight);

  const fillLight = new AmbientLight('#16161d', 0.42);
  stage.add(fillLight);
  owned.push(fillLight);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;
    const role = item.role || '';
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? (role === 'caption' ? 0.09 : 0.2),
      color: role === 'label' || role === 'caption' ? '#e8ecf2' : '#e8ecf2',
      align: 'left',
      letterSpacingPx: /label|caption|cta/i.test(role) ? 5 : 0
    });
    textObject.position.set(-1.18, -0.93, -0.28);
    card.add(textObject);
    owned.push(textObject);
  }

  const settle = gsap.timeline();
  settle.fromTo(
    card.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.42,
      ease: 'power3.out'
    }
  ).to(card.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, 0.42);
  timelines.push(settle);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply !== 'function') continue;
    const result = apply(root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      const scene = gltf.scene;
      loadedMesh.add(scene);

      const bounds = new Box3().setFromObject(scene);
      const center = new Vector3();
      const size = new Vector3();
      bounds.getCenter(center);
      bounds.getSize(size);

      scene.position.sub(center);

      const maxDimension = Math.max(size.x, size.y, size.z, 0.001);
      const fitScale = 1.62 / maxDimension;
      scene.scale.setScalar(fitScale);
      loadedMesh.position.set(0, 0.14, -0.28);

      const entrance = gsap.timeline();
      entrance.fromTo(
        loadedMesh.position,
        { y: 0.54 },
        {
          y: 0.14,
          duration: 0.7,
          ease: 'power3.out'
        }
      );
      timelines.push(entrance);
    }).catch(() => {});
  }

  root.userData.handlers = {
    hover(active = true) {
      if (disposed) return;
      if (hoverTween) hoverTween.kill();

      hoverTween = gsap.to(card.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out'
      });
      timelines.push(hoverTween);
    },
    click() {
      if (disposed) return;

      const press = gsap.timeline();
      press.to(card.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      }).to(card.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.36,
        ease: 'back.out(2)'
      });
      timelines.push(press);

      ctx.emit('hub-features.select', {
        node: config.id ?? 'hub-features-card-0'
      });
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      if (typeof result?.cleanup === 'function') result.cleanup();
    }

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    const disposedGeometries = new Set();
    const disposedMaterials = new Set();

    root.traverse((object) => {
      if (object.geometry && !disposedGeometries.has(object.geometry)) {
        disposedGeometries.add(object.geometry);
        object.geometry.dispose();
      }

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) {
          if (entry && !disposedMaterials.has(entry)) {
            disposedMaterials.add(entry);
            entry.dispose();
          }
        }
      } else if (material && !disposedMaterials.has(material)) {
        disposedMaterials.add(material);
        material.dispose();
      }
    });

    root.clear();
  };

  return root;
}
